      href: 'http://oldmatecranes.com.au/'
  },



  title: 'Kitty McKitty',
  imageUrl: '01.jpg',
  imageWidth: 300,
};

export default function Home() {
  return (
    <>
    <section className='container-fluid px-0 min-vh-100 bg-image'>
    <section className='container-fluid px-0 min-vh-100 d-flex justify-content-center align-items-center bg-gradient-black'>
      <article>
      <img src={home.imageUrl} className='avatar' alt='' width={home.imageWidth} />
          <h2>Welcome to my app</h2>
          <h1>{home.title}</h1>
          <p>Hello there. How do you do?</p>

      </article>
    </section>
    </section>
    </>
  );
}
